const makeNativeHistoryHarness = Effect.fnUntraced(function* () {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const home = yield* fs.makeTempDirectoryScoped({ prefix: "pi-native-history-home-" });
  const directory = path.join(home, ".pi", "agent", "sessions", "workspace");
  yield* fs.makeDirectory(directory, { recursive: true });
  const sourceFile = path.join(directory, "source.jsonl");
  const forkFile = path.join(directory, "fork.jsonl");
  const sourceSessionId = recordedIdleState(sourceFile).sessionId;
  const forkSessionId = "00000000-0000-4000-8000-000000000003";
  const fake = yield* makeFakePi;
  const forkFake = yield* makeFakePi;
  const { runtime } = yield* openRuntime(fake, "default", THREAD_ID, SESSION_ID, forkFake).pipe(
    Effect.provideService(HostProcess.HomeDirectory, home));
  fake.queueState({ sessionFile: sourceFile });
  const source = yield* runtime.ensureThread({
    threadId: THREAD_ID, modelSelection: modelSelection("default"), runtimePolicy,
  });
  const header = { type: "session", version: 3, cwd: runtime.providerSession.cwd };
  yield* fs.writeFileString(sourceFile, JSON.stringify({ ...header, id: sourceSessionId }) + "\n");
  yield* fs.writeFileString(forkFile, JSON.stringify({ ...header, id: forkSessionId }) + "\n");
  return { fs, path, home, header, runtime, source, fake, forkFake, sourceFile, sourceSessionId, forkFile, forkSessionId };
});

it.effect("adopts native Pi metadata without creating a session or sending a prompt", () =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const home = yield* fs.makeTempDirectoryScoped({ prefix: "pi-native-home-" });
    const cwd = yield* fs.makeTempDirectoryScoped({ prefix: "pi-native-workspace-" });
    const directory = path.join(home, ".pi", "agent", "sessions", "workspace");
    yield* fs.makeDirectory(directory, { recursive: true });
    const file = path.join(directory, "native.jsonl");
    const header = { type: "session", version: 3, id: "00000000-0000-4000-8000-000000000002", cwd };
    yield* fs.writeFileString(file, JSON.stringify(header) + "\n");
    const fake = yield* makeFakePi;
    for (let index = 0; index < 5; index++) fake.queueState({ sessionFile: file });
    fake.queueEntries({ entries: [], leafId: null });
    fake.queueEntries({ entries: [], leafId: null });
    const nativeEntries = [sessionMessage("saved-user", null, "user", 0),
      { ...sessionMessage("saved-assistant", "saved-user", "assistant", 1),
        message: { role: "assistant", content: [], stopReason: "stop" } }];
    fake.queueEntries({ entries: nativeEntries, leafId: "saved-assistant" });
    const policy = ProviderAdapter.ProviderAdapterV2RuntimePolicy.make({ cwd, runtimeMode: "approval-required", interactionMode: "default" });
    const adapter = yield* makePiAdapterV2({ instanceId: PI_INSTANCE_ID,
      settings: { enabled: true, binaryPath: "pi", launchArgs: "", customModels: [] }, environment: { HOME: home } }).pipe(
        Effect.provideService(ChildProcessSpawner.ChildProcessSpawner, fake.spawner),
        Effect.provideService(HostProcess.HomeDirectory, home));
    const runtime = yield* adapter.openSession({ threadId: THREAD_ID, providerSessionId: SESSION_ID,
      modelSelection: modelSelection("default"), runtimePolicy: policy, initialNativeThreadId: file });
    const evidence = readPiSessionEvidence(runtime)!;
    assert.equal((yield* evidence.probe).protocol, "pi.rpc-jsonl:get_state+get_entries");
    const ensure = { threadId: THREAD_ID, providerSessionId: SESSION_ID, modelSelection: modelSelection("default"), runtimePolicy: policy };
    const snapshot = yield* evidence.readLegacy({ nativeSessionId: file, turnId: "saved-user", messageId: "saved-assistant", ensure });
    assert.equal(snapshot.providerThread.nativeThreadRef?.nativeId, file);
    assert.equal(snapshot.providerThread.nativeConversationHeadRef?.nativeId, "saved-assistant");
    assert.deepEqual(snapshot.providerTurns, []);
    assert.deepEqual(snapshot.nativeHistory, { nativeSessionId: file,
      completedTurnRefs: [{ driver: PI_PROVIDER, nativeId: "saved-user", strength: "strong" }] });
    yield* runtime.resumeThread({ providerThread: snapshot.providerThread });
    for (const stopReason of [undefined, "error", "aborted", "toolUse"]) {
      const incompleteEntries = nativeEntries.map(entry => entry.id === "saved-assistant"
        ? { ...entry, message: { ...entry.message, stopReason } } : entry);
      fake.queueState({ sessionFile: file });
      fake.queueState({ sessionFile: file });
      fake.queueState({ sessionFile: file });
      fake.queueEntries({ entries: incompleteEntries, leafId: "saved-assistant" });
      fake.queueEntries({ entries: incompleteEntries, leafId: "saved-assistant" });
      assert.equal((yield* evidence.readLegacy({ nativeSessionId: file, turnId: "saved-user", ensure }).pipe(Effect.result))._tag, "Failure");
    }
    assert.isFalse(fake.allRequests().some(request => request.type === "prompt" || request.type === "new_session"));
    const switches = fake.allRequests().filter(request => request.type === "switch_session").length;
    yield* fs.writeFileString(file, JSON.stringify({ ...header, cwd: "/foreign-workspace" }) + "\n");
    assert.equal((yield* evidence.readLegacy({ nativeSessionId: file, ensure }).pipe(Effect.result))._tag, "Failure");
    assert.equal(fake.allRequests().filter(request => request.type === "switch_session").length, switches);
  }).pipe(Effect.scoped, Effect.provide(layerTest)),
);
it.effect("proves only successful assistant segments on the complete active native ancestry", () =>
  Effect.gen(function* () {
    const { runtime, source, fake, sourceFile } = yield* makeNativeHistoryHarness();
    const user = (id: string, parentId: string | null) => sessionMessage(id, parentId, "user", 0);
    const assistant = (id: string, parentId: string, stopReason?: string) => ({
      ...sessionMessage(id, parentId, "assistant", 1),
      message: { role: "assistant", content: [], ...(stopReason ? { stopReason } : {}) },
    });
    const cases: Array<{ label: string; entries: unknown[]; leafId: string; refs: string[]; invalid?: boolean }> = [
      { label: "user alone", entries: [user("u", null)], leafId: "u", refs: [] },
      { label: "idle assistant without terminal", entries: [user("u", null), assistant("a", "u")], leafId: "a", refs: [] },
      ...["stop", "length"].map(stopReason => ({ label: stopReason,
        entries: [user("u", null), assistant("a", "u", stopReason)], leafId: "a", refs: ["u"] })),
      { label: "latest failed assistant wins", entries: [
        user("u", null), assistant("a", "u", "stop"), assistant("failed", "a", "error"),
      ], leafId: "failed", refs: [] },
      { label: "completion cannot cross a user boundary", entries: [
        user("u1", null), user("u2", "u1"), assistant("a2", "u2", "stop"),
      ], leafId: "a2", refs: ["u2"] },
      { label: "abandoned successful branch is ignored", entries: [
        user("u", null), assistant("a", "u", "aborted"),
        user("abandoned-u", "u"), assistant("abandoned-a", "abandoned-u", "stop"),
      ], leafId: "a", refs: [] },
      { label: "missing active ancestor", entries: [assistant("a", "missing", "stop")], leafId: "a", refs: [], invalid: true },
      { label: "active cycle", entries: [user("u", "a"), assistant("a", "u", "stop")], leafId: "a", refs: [], invalid: true },
      { label: "duplicate native id", entries: [user("u", null), user("u", null)], leafId: "u", refs: [], invalid: true },
      { label: "empty native id", entries: [user("", null), assistant("a", "", "stop")], leafId: "a", refs: [], invalid: true },
    ];
    for (const entry of cases) {
      fake.queueState({ sessionFile: sourceFile });
      fake.queueEntries({ entries: entry.entries, leafId: entry.leafId });
      const outcome = yield* runtime.readThreadSnapshot({ providerThread: source }).pipe(Effect.result);
      assert.equal(outcome._tag, entry.invalid ? "Failure" : "Success", entry.label);
      if (outcome._tag === "Success") {
        assert.deepEqual(outcome.success.providerTurns, [], entry.label);
        assert.deepEqual(outcome.success.nativeHistory?.completedTurnRefs.map(ref => ref.nativeId) ?? [], entry.refs, entry.label);
        assert.equal(outcome.success.providerThread.nativeMetadata?.modelSelection, undefined, entry.label);
      }
    }
    assert.isFalse(fake.allRequests().some(request => request.type === "prompt" || request.type === "new_session"));
  }).pipe(Effect.scoped, Effect.provide(layerTest)),
);

