it.effect.each([
  { historical: false, trailingUserOnly: false },
  { historical: true, trailingUserOnly: false },
  { historical: true, trailingUserOnly: true },
])(
  "forks a graph-free completed native boundary, historical=$historical, pending-successor=$trailingUserOnly",
  ({ historical, trailingUserOnly }) => Effect.gen(function* () {
    const { runtime, source, fake, forkFake, sourceFile, forkFile, forkSessionId } = yield* makeNativeHistoryHarness();
    const entries = [
      sessionMessage("native-u1", null, "user", 0),
      { ...sessionMessage("native-a1", "native-u1", "assistant", 1),
        message: { role: "assistant", content: [], stopReason: "stop" } },
      ...(historical ? [
        sessionMessage("native-u2", "native-a1", "user", 2),
        ...(trailingUserOnly ? [] : [{ ...sessionMessage("native-a2", "native-u2", "assistant", 3),
          message: { role: "assistant", content: [], stopReason: "stop" } }]),
      ] : []),
    ];
    forkFake.queueEntries({ entries, leafId: historical ? (trailingUserOnly ? "native-u2" : "native-a2") : "native-a1" });
    forkFake.queueState({ sessionFile: forkFile, sessionId: forkSessionId });
    forkFake.queueState({ sessionFile: forkFile, sessionId: forkSessionId });
    fake.queueState({ sessionFile: forkFile, sessionId: forkSessionId });
    const forked = yield* runtime.forkThread({
      sourceProviderThread: source, sourceProviderTurns: [],
      nativeCompletedTurnRef: { driver: PI_PROVIDER, nativeId: "native-u1", strength: "strong" },
      targetThreadId: ThreadId.make("native-history-fork-target"),
    });
    assert.deepEqual(forkFake.allRequests().filter(request => request.type === "fork").map(request => request.entryId),
      historical ? ["native-u2"] : []);
    assert.equal(forked.nativeThreadRef?.nativeId, forkFile);
    fake.queueState({ sessionFile: forkFile, sessionId: forkSessionId });
    // Append-order includes the discarded branch; only the target's active ancestry survives.
    fake.queueEntries({ entries, leafId: "native-a1" });
    const snapshot = yield* runtime.readThreadSnapshot({ providerThread: forked });
    assert.deepEqual(snapshot.providerTurns, []);
    assert.deepEqual(snapshot.nativeHistory, { nativeSessionId: forkFile,
      completedTurnRefs: [{ driver: PI_PROVIDER, nativeId: "native-u1", strength: "strong" }] });
    assert.equal(snapshot.providerThread.nativeConversationHeadRef?.nativeId, "native-a1");
    assert.equal(snapshot.providerThread.nativeMetadata?.modelSelection, undefined);
    for (const providerThread of [
      { ...forked, driver: ProviderDriverKind.make("muse") },
      { ...forked, providerInstanceId: ProviderInstanceId.make("foreign-instance") },
    ]) assert.equal((yield* runtime.readThreadSnapshot({ providerThread }).pipe(Effect.result))._tag, "Failure");
    fake.queueState({ sessionFile: forkFile, sessionId: "foreign-native-id" });
    assert.equal((yield* runtime.readThreadSnapshot({ providerThread: forked }).pipe(Effect.result))._tag, "Failure");
    fake.queueState({ sessionFile: sourceFile });
    assert.equal((yield* runtime.readThreadSnapshot({ providerThread: forked }).pipe(Effect.result))._tag, "Failure");
    assert.isFalse(fake.allRequests().some(request => request.type === "prompt" || request.type === "new_session"));
    assert.isFalse(forkFake.allRequests().some(request => request.type === "prompt" || request.type === "new_session"));
  }).pipe(Effect.scoped, Effect.provide(layerTest)),
);

